def set_left_most_unset_bit(n):
    # If n is 0, the leftmost unset bit is the least significant bit (0th bit)
    if n == 0:
        return 1

    # If n is a power of 2, the leftmost unset bit is the next bit
    if (n & (n - 1)) == 0:
        return n << 1

    # Find the position of the leftmost unset bit
    pos = 0
    while n & (1 << pos):
        pos += 1

    # Set the leftmost unset bit
    return n | (1 << pos)

