def geometric_sum(n):
    # Base case: if n is 0, the sum is 1 (since 2^0 = 1)
    if n == 0:
        return 1
    # Recursive case: calculate the sum of the current term (2^-n) and the sum of the rest
    else:
        return (1 / (2 ** n)) + geometric_sum(n - 1)

