    if isinstance(d, dict):
        # If the dictionary is not empty, calculate the depth
        if d:
            # Recursively find the depth of each value in the dictionary
            return 1 + max(map(dict_depth, d.values()))
        # If the dictionary is empty, its depth is 1
        return 1
    # If the input is not a dictionary, its depth is 0
