def is_majority(arr, n, x):
    # Find the first occurrence of x in arr
    first_occurrence = -1
    for i in range(n):
        if arr[i] == x:
            first_occurrence = i
            break

    # If x is not found, it cannot be the majority element
    if first_occurrence == -1:
        return False

    # Calculate the last occurrence of x
    last_occurrence = first_occurrence
    for i in range(first_occurrence + 1, n):
        if arr[i] != x:
            break
        last_occurrence += 1

    # Check if the number of occurrences of x is more than n/2
    if (last_occurrence - first_occurrence + 1) > n // 2:
        return True
    else:
        return False

